tok2 = open(gt).read().strip()
check("--rotate replaces both files, the old token stops matching, nothing printed", r.returncode == 0 and tok2 != tok and open(gh).read().strip() == hashlib.sha256(tok2.encode()).hexdigest() and tok2 not in r.stdout + r.stderr, r.stdout)
check("settings are saved for recreate", open(os.path.join(root, "herstr", ".settings.json")).read() == '{"image": "bridgeai-place:latest", "bind": "10.9.8.7", "gpu": true, "udp": [], "sunshine": null, "games": false}', open(os.path.join(root, "herstr", ".settings.json")).read())
envf2 = os.path.join(root, "herstr", ".desktop.env"); before = open(envf2).read()
open(log, "w").close()
r = run("recreate", "herstr", "--image", "bridgeai-place-resolve:latest")
c3 = open(log).read().splitlines()
check("recreate removes the container and makes it again with the new image, same ports and the GPU kept", r.returncode == 0 and any(l.startswith("rm place-herstr-desktop") for l in c3) and any("-p 10.9.8.7:3030:3000" in l and "--runtime nvidia" in l and l.endswith("bridgeai-place-resolve:latest") for l in c3), (r.stdout, r.stderr, c3))
check("recreate keeps the login and the folders (nothing regenerated)", open(envf2).read() == before and os.path.isdir(os.path.join(root, "herstr", "desktop")), "")
r = run("recreate", "herstr", "--no-gpu")
check("--no-gpu drops the NVIDIA runtime", r.returncode == 0 and "--runtime" not in open(log).read().splitlines()[-1], open(log).read().splitlines()[-1])
r = run("recreate", "herstr", "--bind", "10.9.8.8")
check("recreate --bind moves the place to another LAN address and remembers it", "-p 10.9.8.8:3030:3000" in open(log).read().splitlines()[-1] and '"bind": "10.9.8.8"' in open(os.path.join(root, "herstr", ".settings.json")).read(), "")
r = run("recreate", "herstr", "--bind", "8.8.8.8")
