bd = os.path.join(tmp, "rb"); os.makedirs(bd)
rr = lambda d: subprocess.run(["bash", os.path.join(HERE, "build-resolve.sh"), d], capture_output=True, text=True)
check("build-resolve.sh without a folder: usage, rc 2", rr(os.path.join(tmp, "nope")).returncode == 2)
check("build-resolve.sh with an empty folder: asks for the zip, rc 2", (lambda r: r.returncode == 2 and "no DaVinci_Resolve" in r.stderr)(rr(bd)))
open(os.path.join(bd, "DaVinci_Resolve_Studio_21.2_Linux.zip"), "w").write("x")
r = rr(bd)
check("build-resolve.sh refuses a Studio file: its licence is a USB key tied to one host, rc 3", r.returncode == 3 and "Studio" in r.stderr, r.stderr)
os.remove(os.path.join(bd, "DaVinci_Resolve_Studio_21.2_Linux.zip")); open(os.path.join(bd, "DaVinci_Resolve_21.2_Linux.zip"), "w").write("x")
r = rr(bd)
check("build-resolve.sh with the free zip but no makeresolvedeb: asks for it, rc 2", r.returncode == 2 and "makeresolvedeb" in r.stderr, r.stderr)
import shutil as _sh
if _sh.which("ffmpeg") and _sh.which("ffprobe"):
    w = os.path.join(tmp, "media"); os.makedirs(w)
    src = os.path.join(w, "game.mp4")
    subprocess.run(["ffmpeg", "-loglevel", "error", "-f", "lavfi", "-i", "testsrc=size=640x360:rate=30:duration=3", "-f", "lavfi", "-i", "sine=frequency=440:duration=3",
                    "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest", src], check=True)
    probe = lambda f: subprocess.run(["ffprobe", "-v", "error", "-show_entries", "stream=codec_name", "-of", "csv=p=0", f], capture_output=True, text=True).stdout.split()
    sh = lambda *a: subprocess.run(["sh", *a], capture_output=True, text=True)
    TR = os.path.join(HERE, "bin", "to-resolve")
    tr = lambda *args, e=None: subprocess.run([sys.executable, "-I", TR, "--gpu-decode", "off", *args], capture_output=True, text=True, env=e or os.environ)
    fprobe = lambda f, entries: subprocess.run(["ffprobe", "-v", "error", "-select_streams", "v:0", "-show_entries", "stream=" + entries, "-of", "csv=p=0", f], capture_output=True, text=True).stdout.strip()
    r = tr(src, os.path.join(w, "full.mov"))
    check("to-resolve (default, free edition): H.264 + AAC becomes DNxHR + PCM, and says why", r.returncode == 0 and probe(os.path.join(w, "full.mov")) == ["dnxhd", "pcm_s24le"] and "h264 video" in r.stderr and "AAC" in r.stderr, (r.stderr[-300:], probe(os.path.join(w, "full.mov"))))
    r = tr("--audio", src, os.path.join(w, "aud.mov"))
    check("--audio (the old name) on an H.264 source still re-encodes the video: no silent copy", r.returncode == 0 and probe(os.path.join(w, "aud.mov")) == ["dnxhd", "pcm_s24le"], (r.stderr[-200:], probe(os.path.join(w, "aud.mov"))))
    r = tr(os.path.join(w, "full.mov"), os.path.join(w, "again.mov"))
    check("a constant-rate progressive DNxHR + PCM source is copied untouched (and it says so)", r.returncode == 0 and probe(os.path.join(w, "again.mov")) == ["dnxhd", "pcm_s24le"] and "copied untouched" in r.stderr, r.stderr[-300:])
    r = tr("--full", os.path.join(w, "full.mov"), os.path.join(w, "forced.mov"))
    check("--full re-encodes even a readable source", r.returncode == 0 and "--full asked" in r.stderr and "copied untouched" not in r.stderr, r.stderr[-200:])
    r = tr("--edition", "studio", src, os.path.join(w, "studio.mov"))
    check("--edition studio leaves H.264 alone (copied) and still turns AAC into PCM", r.returncode == 0 and probe(os.path.join(w, "studio.mov")) == ["h264", "pcm_s24le"], (r.stderr[-200:], probe(os.path.join(w, "studio.mov"))))
    tiers = {}
    for q in ("lb", "hq"):
        tr("--quality", q, src, os.path.join(w, f"q{q}.mov")); tiers[q] = os.path.getsize(os.path.join(w, f"q{q}.mov"))
    check("--quality lb is smaller than hq (the DNxHR tier is honoured)", tiers["lb"] < tiers["hq"], tiers)
    tr("--quality", "hqx", src, os.path.join(w, "qhqx.mov"))
    check("--quality hqx is 10-bit", fprobe(os.path.join(w, "qhqx.mov"), "pix_fmt") == "yuv422p10le", fprobe(os.path.join(w, "qhqx.mov"), "pix_fmt"))
    vfr = os.path.join(w, "vfr.mp4")
    subprocess.run(["ffmpeg", "-loglevel", "error", "-f", "lavfi", "-i", "testsrc=size=320x180:rate=60:duration=4", "-vf", "select='lt(mod(n,3),2)',setpts=N/(40*TB)", "-fps_mode", "vfr",
                    "-c:v", "libx264", "-pix_fmt", "yuv420p", vfr], check=True)
    r = tr(vfr, os.path.join(w, "vfr.mov"))
    rates = fprobe(os.path.join(w, "vfr.mov"), "r_frame_rate,avg_frame_rate").split(",")
    check("a variable-rate source comes out at one constant standard rate", r.returncode == 0 and "variable frame rate" in r.stderr and len(set(rates)) == 1, (r.stderr[-300:], rates))
    r = tr("--framerate", "25", vfr, os.path.join(w, "vfr25.mov"))
    check("--framerate forces the rate on a variable-rate file", fprobe(os.path.join(w, "vfr25.mov"), "r_frame_rate") == "25/1", fprobe(os.path.join(w, "vfr25.mov"), "r_frame_rate"))
    ilace = os.path.join(w, "ilace.mp4")
    subprocess.run(["ffmpeg", "-loglevel", "error", "-f", "lavfi", "-i", "testsrc=size=320x180:rate=50:duration=2", "-vf", "interlace", "-c:v", "libx264", "-flags", "+ilme+ildct", "-pix_fmt", "yuv420p", ilace], check=True)
    fo = fprobe(ilace, "field_order")
    r = tr(ilace, os.path.join(w, "ilace.mov"))
    check("an interlaced source is deinterlaced", fo in ("tt", "bb", "tb", "bt") and r.returncode == 0 and "interlaced" in r.stderr and fprobe(os.path.join(w, "ilace.mov"), "field_order") in ("progressive", "unknown", ""), (fo, r.stderr[-200:]))
    r = tr("--no-deinterlace", ilace, os.path.join(w, "ilace2.mov"))
    check("--no-deinterlace leaves the fields alone", "interlaced" not in r.stderr, r.stderr[-200:])
    two = os.path.join(w, "two.mkv")
    subprocess.run(["ffmpeg", "-loglevel", "error", "-f", "lavfi", "-i", "testsrc=size=320x180:rate=25:duration=2", "-f", "lavfi", "-i", "sine=frequency=300:duration=2", "-f", "lavfi", "-i", "sine=frequency=600:duration=2",
                    "-map", "0", "-map", "1", "-map", "2", "-c:v", "libx264", "-pix_fmt", "yuv420p", "-c:a", "aac", two], check=True)
    r = tr(two, os.path.join(w, "two.mov"))
    check("every audio track is kept, all PCM", subprocess.run(["ffprobe", "-v", "error", "-select_streams", "a", "-show_entries", "stream=codec_name", "-of", "csv=p=0", os.path.join(w, "two.mov")], capture_output=True, text=True).stdout.split() == ["pcm_s24le", "pcm_s24le"], r.stderr[-200:])
    silent = os.path.join(w, "silent.mp4")
    subprocess.run(["ffmpeg", "-loglevel", "error", "-f", "lavfi", "-i", "testsrc=size=320x180:rate=25:duration=2", "-c:v", "libx264", "-pix_fmt", "yuv420p", silent], check=True)
    r = tr(silent, os.path.join(w, "silent.mov"))
    check("a video with no sound works", r.returncode == 0 and probe(os.path.join(w, "silent.mov")) == ["dnxhd"], r.stderr[-200:])
    r = tr("--dry-run", src, os.path.join(w, "dry.mov"))
    check("--dry-run says what it would do and writes nothing", r.returncode == 0 and "dry-run" in r.stderr and not os.path.exists(os.path.join(w, "dry.mov")), r.stderr[-200:])
    # a folder: mirrors the tree, ignores what is not video, resumes, never walks into its own output
    fol = os.path.join(w, "lib"); os.makedirs(os.path.join(fol, "trip", "day1")); os.makedirs(os.path.join(fol, "trip", "day2"))
    for dest in (os.path.join(fol, "a.mp4"), os.path.join(fol, "trip", "day1", "b.mp4"), os.path.join(fol, "trip", "day2", "c.mkv")):
        shutil.copy(src if dest.endswith(".mp4") else two, dest)
    open(os.path.join(fol, "notes.txt"), "w").write("not video")
    r = tr(fol)
    outd = fol + "-resolve"
    check("a folder is converted with its tree mirrored and the non-video file ignored", r.returncode == 0 and sorted(os.path.relpath(os.path.join(dp, f), outd) for dp, _, fs in os.walk(outd) for f in fs) == ["a.mov", "trip/day1/b.mov", "trip/day2/c.mov"], (r.stderr[-400:], os.listdir(outd) if os.path.isdir(outd) else None))
    check("the folder run reports a count", "done 3" in r.stderr, r.stderr[-200:])
    check("it says where the converted files are (full path) and that Resolve imports from there, and each line has its output and size", f"full path {outd}" in r.stderr and "Media Storage" in r.stderr and " MB)" in r.stderr and "b.mov" in r.stderr, r.stderr[-700:])
    r = tr(fol)
    check("running it again skips what is already there (resume)", r.returncode == 0 and "skipped 3" in r.stderr and "done" not in r.stderr.split("to-resolve: skipped")[-1], r.stderr[-300:])
    r = tr(fol, os.path.join(fol, "out-inside"))
    check("an output folder inside the source is never walked back into", r.returncode == 0 and not any("out-inside" in x for x in r.stderr.splitlines() if "[" in x and "skipped" not in x and "done" not in x), r.stderr[-300:])
    r = tr(os.path.join(w, "nope.mp4"))
    check("a path that is not there is usage, rc 2", r.returncode == 2, r.stderr)
    r = tr(src, src)
    check("OUT equal to FILE is refused", r.returncode == 2 and "differ" in r.stderr, r.stderr)
    wrap = os.path.join(w, "ffmpeg-nogpu"); open(wrap, "w").write('#!/bin/sh\nfor a in "$@"; do [ "$a" = "-hwaccel" ] && { echo "no cuda here" >&2; exit 1; }; done\nexec ffmpeg "$@"\n'); os.chmod(wrap, 0o755)
    e = dict(os.environ, TO_RESOLVE_FFMPEG=wrap)
    r = subprocess.run([sys.executable, "-I", TR, "--gpu-decode", "on", src, os.path.join(w, "hwfail.mov")], capture_output=True, text=True, env=e)
    check("a file the GPU decode cannot take is retried on the CPU and still comes out", r.returncode == 0 and probe(os.path.join(w, "hwfail.mov")) == ["dnxhd", "pcm_s24le"] and "decoded on the GPU" not in r.stderr, r.stderr[-300:])
    open(os.path.join(w, "broken.mp4"), "w").write("not a video at all")
    r = tr(os.path.join(w, "broken.mp4"))
    check("a broken file is skipped with a reason, not a crash", r.returncode == 0 and "no video stream" in r.stderr, (r.returncode, r.stderr[-200:]))
    r = sh(os.path.join(HERE, "bin", "from-resolve"), os.path.join(w, "full.mov"), os.path.join(w, "back.mp4"))
    check("from-resolve: H.264 + AAC mp4 back from the intermediate", r.returncode == 0 and probe(os.path.join(w, "back.mp4")) == ["h264", "aac"], (r.stderr[-200:], probe(os.path.join(w, "back.mp4"))))
    r = sh(os.path.join(HERE, "bin", "from-resolve"), "--max-mb", "1", os.path.join(w, "full.mov"), os.path.join(w, "small.mp4"))
    check("from-resolve --max-mb: the result fits the size asked", r.returncode == 0 and os.path.getsize(os.path.join(w, "small.mp4")) < 1_048_576, os.path.getsize(os.path.join(w, "small.mp4")) if os.path.exists(os.path.join(w, "small.mp4")) else r.stderr)
    r = sh(os.path.join(HERE, "bin", "from-resolve"), "--max-mb", "0", os.path.join(w, "full.mov"))
    check("from-resolve: a size that cannot hold a watchable video is refused, rc 3 (or a bad number rc 2)", r.returncode in (2, 3), r.returncode)
    r = sh(os.path.join(HERE, "bin", "from-resolve"), "--max-mb", "abc", os.path.join(w, "full.mov"))
    check("from-resolve: a non-numeric size is rc 2", r.returncode == 2, r.returncode)
else:
    print("skip to-resolve / from-resolve tests: no ffmpeg here")
print("place_selftest: " + ("FAILED: " + ", ".join(fails) if fails else "all ok"))
sys.exit(1 if fails else 0)
